c(r"Найдите угловой коэффициент касательной к $y=x^3$ в точке $x_0=2$", r"$y'=3x^2$, $k=3\cdot4=12$")
c(r"Правила дифференцирования суммы, произведения и частного", r"$(u\pm v)'=u'\pm v'$, $\;(uv)'=u'v+uv'$, $\;\left(\dfrac uv\right)'=\dfrac{u'v-uv'}{v^2}$")
c(r"Производная сложной функции $y=f(u(x))$", r"$y'=f'(u)\cdot u'(x)$ — производная внешней функции на производную внутренней")
c(r"Производные $x^n$, $e^x$, $a^x$, $\ln x$", r"$(x^n)'=nx^{n-1}$, $\;(e^x)'=e^x$, $\;(a^x)'=a^x\ln a$, $\;(\ln x)'=\dfrac1x$")
c(r"Производные $\sin x$, $\cos x$, $\operatorname{tg}x$, $\operatorname{ctg}x$", r"$\cos x$, $\;-\sin x$, $\;\dfrac1{\cos^2x}$, $\;-\dfrac1{\sin^2x}$")
c(r"Производные $\arcsin x$, $\arccos x$, $\operatorname{arctg}x$", r"$\dfrac1{\sqrt{1-x^2}}$, $\;-\dfrac1{\sqrt{1-x^2}}$, $\;\dfrac1{1+x^2}$")
c(r"Найдите производную $y=\sin3x$", r"$y'=3\cos3x$")
